-- pintopets_photos: tenant-scoped rows behind /photos (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_photos (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            uploaded_by_user_uuid UUID NOT NULL,
            storage_key VARCHAR(255) NOT NULL,
            thumb_key VARCHAR(255),
            mime_type VARCHAR(255) NOT NULL,
            bytes INTEGER NOT NULL,
            width INTEGER,
            height INTEGER,
            caption VARCHAR(255),
            alt_text VARCHAR(255),
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_photos_bytes_range CHECK (bytes BETWEEN 1 AND 100000000)
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_photos_namespace ON pintopets_photos (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_photos_pet ON pintopets_photos (namespace_id, pet_uuid)")
end
